// wallet-final/lib/top20Logos.js — Phase 7, étape 1/2 : FONDATIONS (2026-10-26)
// ─────────────────────────────────────────────────────────────────
//  Logos OFFICIELS des 20 premières cryptos par capitalisation,
//  téléchargés depuis CoinGecko (même CDN que le code existant :
//  coin-images.coingecko.com, variantes /small/, convertis en PNG
//  <= 128 px — en fait 50x50 tels que servis par CoinGecko — et
//  encodés en base64 pour éviter tout échec CDN (même technique que
//  les 8 logos de la Phase 5). Aucun logo inventé : si un
//  téléchargement avait échoué, l'entrée aurait été omise et le
//  fallback existant (initiale / image distante) s'appliquerait.
//  Ordre de capitalisation au 2026-10-26 (CoinGecko /coins/markets).
//  Attention : le logo XRP officiel est BLANC sur transparent — sur
//  fond clair il sera invisible ; l'intégrateur doit le rendre sur
//  pastille sombre ou garder le fallback pour ce cas précis.
//
//  Style : CommonJS comme les autres lib/ (cf. phase7.js).
// ─────────────────────────────────────────────────────────────────

'use strict';

const TOP20_LOGOS = {
  'bitcoin': 'data:image/png;base64,',
  'ethereum': 'data:image/png;base64,',
  'tether': 'data:image/png;base64,',
  'binancecoin': 'data:image/png;base64,',
  'ripple': 'data:image/png;base64,',
  'usd-coin': 'data:image/png;base64,',
  'solana': 'data:image/png;base64,',
  'tron': 'data:image/png;base64,',
  'figure-heloc': 'data:image/png;base64,',
  'zcash': 'data:image/png;base64,',
  'hyperliquid': 'data:image/png;base64,',
  'dogecoin': 'data:image/png;base64,',
  'monero': 'data:image/png;base64,',
  'usds': 'data:image/png;base64,',
  'whitebit': 'data:image/png;base64,',
  'chainlink': 'data:image/png;base64,',
  'leo-token': 'data:image/png;base64,',
  'cardano': 'data:image/png;base64,',
  'near': 'data:image/png;base64,',
  'stellar': 'data:image/png;base64,',
};

// Lookup : data URI PNG ou null (jamais d'exception, jamais de
// placeholder inventé — null => fallback existant de l'UI).
function getTop20Logo(cgId) {
  if (typeof cgId !== 'string') return null;
  return TOP20_LOGOS[cgId.toLowerCase()] || null;
}

function hasTop20Logo(cgId) {
  return getTop20Logo(cgId) !== null;
}

module.exports = { TOP20_LOGOS, getTop20Logo, hasTop20Logo };
